+  return /^[0-9]/.test(cleaned) ? `_${cleaned}` : cleaned;
 }
+
+const NAME_RE = /^[A-Z_][A-Z0-9_]*$/;

 /** Render variables as the lines of a dotenv file. */
 export function renderEnvFile(vars: Record<string, string>): string {
-  throw new Error("not implemented");
+  const keys = Object.keys(vars).sort();
+  const lines: string[] = [];
+
+  for (const key of keys) {
+    if (!NAME_RE.test(key)) throw new RangeError(`invalid variable name: ${key}`);
+    const val = vars[key];
+    if (val === "") {
+      lines.push(`${key}=`);
+    } else if (SAFE_VALUE_RE.test(val)) {
+      lines.push(`${key}=${val}`);
+    } else {
+      const escaped = val.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\$/g, "\\$").replace(/\n/g, "\\n").replace(/\r/g, "\\r");
+      lines.push(`${key}="${escaped}"`);
+    }
+  }
+
+  return lines.length > 0 ? lines.join("\n") + "\n" : "";
 }

